#include <cstdlib>
#include <iostream>
#include <new>
#include <string>

long g_allocs = 0;  // every heap allocation, counted by a replaced operator new
void* operator new(std::size_t n) {
    ++g_allocs;
    void* p = std::malloc(n);
    if (p == nullptr) throw std::bad_alloc{};
    return p;
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

long allocs_for(std::size_t length) {
    const long before = g_allocs;
    const std::string s(length, 'x');
    return g_allocs - before;
}

int main() {
#if defined(_LIBCPP_VERSION)
    std::cout << "library: libc++\n";
#elif defined(__GLIBCXX__)
    std::cout << "library: libstdc++\n";
#else
    std::cout << "library: another one\n";
#endif
    std::cout << "sizeof(std::string): " << sizeof(std::string) << '\n';
    for (std::size_t length : {15, 16, 22, 23}) {
        std::cout << length << " chars, allocations " << allocs_for(length) << '\n';
    }
    return 0;
}

