    std::cout << std::boolalpha;
    std::cout << "pointer: " << sizeof(void*) << " bytes\n";
    std::cout << "size_t: " << sizeof(std::size_t) << " bytes\n";
    std::cout << "double: " << std::numeric_limits<double>::digits << " bits of precision\n";
    std::cout << "high_resolution_clock is system_clock: "
              << std::is_same_v<high_resolution_clock, std::chrono::system_clock> << '\n';
    std::cout << "high_resolution_clock is steady_clock: "
              << std::is_same_v<high_resolution_clock, std::chrono::steady_clock> << '\n';
    std::cout << "high_resolution_clock is steady: " << high_resolution_clock::is_steady << '\n';
    return 0;
}

