#include <chrono>
#include <ctime>
#include <fstream>
#include <iostream>

// POSIX: read one of the kernel's clocks, in nanoseconds
long long posix_ns(clockid_t clock) {
    timespec ts{};
    clock_gettime(clock, &ts);
    return ts.tv_sec * 1'000'000'000LL + ts.tv_nsec;
}

// the standard: any std::chrono clock, in nanoseconds
template <typename Clock>
long long chrono_ns() {
    const auto since_epoch = Clock::now().time_since_epoch();
    return std::chrono::duration_cast<std::chrono::nanoseconds>(since_epoch).count();
}

bool within_a_second(long long a, long long b) {
    return (a > b ? a - b : b - a) < 1'000'000'000LL;
}

int main() {
    const long long steady = chrono_ns<std::chrono::steady_clock>();
    const long long system = chrono_ns<std::chrono::system_clock>();
    std::cout << std::boolalpha;
    std::cout << "steady_clock matches CLOCK_MONOTONIC: " << within_a_second(steady, posix_ns(CLOCK_MONOTONIC)) << '\n';
    std::cout << "steady_clock matches CLOCK_REALTIME: " << within_a_second(steady, posix_ns(CLOCK_REALTIME)) << '\n';
    std::cout << "system_clock matches CLOCK_REALTIME: " << within_a_second(system, posix_ns(CLOCK_REALTIME)) << '\n';

    double uptime_s = -1.0;  // Linux only: seconds since boot, read from a file
    std::ifstream("/proc/uptime") >> uptime_s;
    const long long uptime_ns = static_cast<long long>(uptime_s * 1e9);
    std::cout << "steady_clock counts from boot: " << within_a_second(steady, uptime_ns) << '\n';
    return 0;
}

