#include <iostream>
#include <thread>
#include <unistd.h>

bool is_power_of_two(long x) {
    return x > 0 && (x & (x - 1)) == 0;
}

int main() {
    const long page = sysconf(_SC_PAGESIZE);
    const long cpus = sysconf(_SC_NPROCESSORS_ONLN);
    const long line = sysconf(_SC_LEVEL1_DCACHE_LINESIZE);  // glibc's, not POSIX's
    const long threads = static_cast<long>(std::thread::hardware_concurrency());
    std::cout << std::boolalpha;
    std::cout << "page size is a power of two: " << is_power_of_two(page) << '\n';
    std::cout << "page size is a multiple of 4096: " << (page % 4096 == 0) << '\n';
    std::cout << "cache line is a power of two: " << is_power_of_two(line) << '\n';
    std::cout << "cache line is 32 to 256 bytes: " << (line >= 32 && line <= 256) << '\n';
    std::cout << "hardware_concurrency matches sysconf: " << (threads == cpus) << '\n';
    return 0;
}

