// -std=c++20
#include <bit>
#include <bitset>
#include <cstdint>
#include <iostream>

[[gnu::noinline]] int popcount_loop(std::uint32_t x) {  // a vendor attribute: stays a real call
    int n = 0;
    for (; x != 0; x >>= 1) n += x & 1;
    return n;
}

int popcount_builtin(std::uint32_t x) {
#if defined(__has_builtin)
#if __has_builtin(__builtin_popcount)
    return __builtin_popcount(x);  // g++ and clang: one instruction where the CPU has one
#endif
#endif
    return popcount_loop(x);  // any other compiler
}

int armed_slots(std::uint32_t mask) {
    if (mask == 0) [[unlikely]] {  // C++20's spelling of __builtin_expect(mask == 0, 0)
        return -1;
    }
    return std::popcount(mask);  // C++20's spelling of __builtin_popcount
}

#if defined(__GNUC__)
const char* kFamily = "GNU-compatible";  // g++, and clang, which defines __GNUC__ too
#else
const char* kFamily = "other";
#endif

int main() {
    for (std::uint32_t mask : {0b1011u, 0xffu, 0x80000001u}) {
        std::cout << mask << ": " << popcount_loop(mask) << ' ' << popcount_builtin(mask) << ' '
                  << std::bitset<32>(mask).count() << ' ' << std::popcount(mask) << '\n';
    }
    std::cout << "armed: " << armed_slots(0b0110u) << ' ' << armed_slots(0) << '\n';
    std::cout << "compiler family: " << kFamily << '\n';
    return 0;
}

