// -std=c++20
#include <bit>
#include <cstdint>
#include <iostream>

[[gnu::noinline]] int lowest_loop(std::uint32_t x) {
    if (x == 0) return 32;
    int n = 0;
    for (; (x & 1) == 0; x >>= 1) ++n;
    return n;
}

int lowest_builtin(std::uint32_t x) {
    if (x == 0) [[unlikely]] {
        return 32;  // __builtin_ctz(0) is undefined, so never pass it 0
    }
#if defined(__has_builtin)
#if __has_builtin(__builtin_ctz)
    return __builtin_ctz(x);
#endif
#endif
    return lowest_loop(x);
}

int main() {
    for (std::uint32_t mask : {0b1000u, 0b0110u, 1u, 0x80000000u, 0u}) {
        std::cout << mask << ": " << lowest_loop(mask) << ' ' << lowest_builtin(mask) << ' '
                  << std::countr_zero(mask) << '\n';
    }
    return 0;
}
